package com.itu.gestionRH.entity.organization;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="POINTAGE_JOURNALIER",uniqueConstraints=@UniqueConstraint(columnNames={"EMPLOYE_ID","DATE_POINTAGE"})) public class PointageJournalier {
 @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="pointageGen") @SequenceGenerator(name="pointageGen",sequenceName="SEQ_POINTAGE_JOURNALIER",allocationSize=1) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="EMPLOYE_ID",nullable=false) private Employe employe; @Column(name="DATE_POINTAGE") private LocalDate datePointage; @Column(name="ENTREE_PREVUE") private LocalDateTime entreePrevue; @Column(name="SORTIE_PREVUE") private LocalDateTime sortiePrevue; @Column(name="ENTREE_REELLE") private LocalDateTime entreeReelle; @Column(name="SORTIE_REELLE") private LocalDateTime sortieReelle; @Column(name="MINUTES_RETARD") private Integer minutesRetard=0; @Column(name="MINUTES_HEURES_SUP") private Integer minutesHeuresSup=0; @Column(nullable=false) private String statut="ABSENT"; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="SAISI_PAR_ID") private Employe saisiPar; @Column(name="DATE_SAISIE") private LocalDateTime dateSaisie=LocalDateTime.now();
 public Long getId(){return id;} public Employe getEmploye(){return employe;} public void setEmploye(Employe v){employe=v;} public LocalDate getDatePointage(){return datePointage;} public void setDatePointage(LocalDate v){datePointage=v;} public LocalDateTime getEntreePrevue(){return entreePrevue;} public void setEntreePrevue(LocalDateTime v){entreePrevue=v;} public LocalDateTime getSortiePrevue(){return sortiePrevue;} public void setSortiePrevue(LocalDateTime v){sortiePrevue=v;} public LocalDateTime getEntreeReelle(){return entreeReelle;} public void setEntreeReelle(LocalDateTime v){entreeReelle=v;} public LocalDateTime getSortieReelle(){return sortieReelle;} public void setSortieReelle(LocalDateTime v){sortieReelle=v;} public Integer getMinutesRetard(){return minutesRetard;} public void setMinutesRetard(Integer v){minutesRetard=v;} public Integer getMinutesHeuresSup(){return minutesHeuresSup;} public void setMinutesHeuresSup(Integer v){minutesHeuresSup=v;} public String getStatut(){return statut;} public void setStatut(String v){statut=v;} public void setSaisiPar(Employe v){saisiPar=v;}
}
